-- PACE AI Hub v1 — PostgreSQL 15+ conceptual executable DDL
-- Application MUST enforce workspace RBAC on every query; RLS is recommended defense-in-depth before production.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE workspace_kind AS ENUM ('personal','team','organization');
CREATE TYPE tool_state AS ENUM ('draft','published','paused','archived');
CREATE TYPE run_state AS ENUM ('queued','running','needs_review','failed','completed','cancelled');
CREATE TYPE report_state AS ENUM ('draft','pending_approval','approved','rejected','sent');
CREATE TYPE membership_role AS ENUM ('viewer','member','editor','admin');
CREATE TYPE reservation_state AS ENUM ('reserved','settled','released','uncertain');
CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entra_oid text UNIQUE NOT NULL, email text NOT NULL, display_name text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind workspace_kind NOT NULL, name text NOT NULL, owner_user_id uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES app_users(id), role membership_role NOT NULL DEFAULT 'member', PRIMARY KEY(workspace_id,user_id));
CREATE TABLE budget_pools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, monthly_limit_usd numeric(18,6) NOT NULL CHECK(monthly_limit_usd>=0), currency text NOT NULL DEFAULT 'USD', active boolean NOT NULL DEFAULT true);
CREATE TABLE budget_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pool_id uuid NOT NULL REFERENCES budget_pools(id), period_month date NOT NULL, spent_usd numeric(18,6) NOT NULL DEFAULT 0 CHECK(spent_usd>=0), reserved_usd numeric(18,6) NOT NULL DEFAULT 0 CHECK(reserved_usd>=0), UNIQUE(pool_id,period_month), CHECK(date_trunc('month',period_month)::date=period_month));
CREATE TABLE provider_credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pool_id uuid NOT NULL REFERENCES budget_pools(id), provider text NOT NULL DEFAULT 'anthropic', vault_ref text NOT NULL, key_fingerprint text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_price_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, model_id text NOT NULL, input_per_million_usd numeric(18,6) NOT NULL, output_per_million_usd numeric(18,6) NOT NULL, effective_from timestamptz NOT NULL, UNIQUE(provider,model_id,effective_from));
CREATE TABLE tools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, template_key text NOT NULL, state tool_state NOT NULL DEFAULT 'draft', current_version int NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tool_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tool_id uuid NOT NULL REFERENCES tools(id) ON DELETE CASCADE, version int NOT NULL, config jsonb NOT NULL, policy jsonb NOT NULL, created_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tool_id,version));
CREATE TABLE tool_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tool_id uuid NOT NULL REFERENCES tools(id), cron_expr text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh', enabled boolean NOT NULL DEFAULT false, last_fired_at timestamptz, UNIQUE(tool_id));
CREATE TABLE source_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), source_kind text NOT NULL, canonical_url text, url_hash bytea, title text NOT NULL, published_at timestamptz, fetched_at timestamptz NOT NULL DEFAULT now(), content_hash bytea, source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(workspace_id,url_hash));
CREATE TABLE runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), tool_id uuid NOT NULL REFERENCES tools(id), tool_version_id uuid NOT NULL REFERENCES tool_versions(id), status run_state NOT NULL DEFAULT 'queued', trigger_kind text NOT NULL CHECK(trigger_kind IN ('manual','schedule')), schedule_slot timestamptz, idempotency_key text NOT NULL, requested_by uuid REFERENCES app_users(id), started_at timestamptz, finished_at timestamptz, error_code text, UNIQUE(tool_id,idempotency_key));
CREATE UNIQUE INDEX uq_schedule_slot ON runs(tool_id,schedule_slot) WHERE schedule_slot IS NOT NULL;
CREATE TABLE run_sources (run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, source_item_id uuid NOT NULL REFERENCES source_items(id), PRIMARY KEY(run_id,source_item_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES runs(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), revision int NOT NULL DEFAULT 1, status report_state NOT NULL DEFAULT 'draft', content jsonb NOT NULL, approved_by uuid REFERENCES app_users(id), approved_at timestamptz, sharepoint_url text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,revision));
CREATE TABLE report_evidence (report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, source_item_id uuid NOT NULL REFERENCES source_items(id), claim_key text NOT NULL, PRIMARY KEY(report_id,source_item_id,claim_key));
CREATE TABLE budget_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid NOT NULL REFERENCES budget_periods(id), run_id uuid NOT NULL REFERENCES runs(id), reserved_usd numeric(18,6) NOT NULL CHECK(reserved_usd>=0), settled_usd numeric(18,6), status reservation_state NOT NULL DEFAULT 'reserved', expires_at timestamptz NOT NULL, UNIQUE(run_id));
CREATE TABLE usage_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL REFERENCES budget_reservations(id), run_id uuid NOT NULL REFERENCES runs(id), price_version_id uuid REFERENCES model_price_versions(id), input_tokens bigint NOT NULL DEFAULT 0 CHECK(input_tokens>=0), output_tokens bigint NOT NULL DEFAULT 0 CHECK(output_tokens>=0), amount_usd numeric(18,6) NOT NULL, event_type text NOT NULL CHECK(event_type IN ('settlement','adjustment','refund')), provider_request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id), channel text NOT NULL DEFAULT 'outlook', recipient_hash text NOT NULL, idempotency_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued', external_message_id text, sent_at timestamptz, error_code text);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, workspace_id uuid REFERENCES workspaces(id), actor_user_id uuid REFERENCES app_users(id), event_type text NOT NULL, resource_type text, resource_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_runs_workspace_created ON runs(workspace_id,started_at DESC);
CREATE INDEX idx_sources_workspace_published ON source_items(workspace_id,published_at DESC);
CREATE INDEX idx_reports_workspace_status ON reports(workspace_id,status);
CREATE INDEX idx_ledger_run ON usage_ledger(run_id,created_at);
CREATE INDEX idx_audit_workspace_time ON audit_events(workspace_id,occurred_at DESC);
-- Production TODO: enforce composite workspace FKs / RLS policies; partition audit by month;
-- never store plaintext secrets; validate JSON config schema in application; migrations via Alembic.
